"""
PlantSathi AI Backend - Rule-Based AI Plant Doctor
Provides context-aware, keyword-matched plant care guidance without an LLM.
All responses are clearly labelled as rule-based, not generated by a language model.
"""
from __future__ import annotations

import logging
import re
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

logger = logging.getLogger(__name__)

_DISCLAIMER = (
    "This guidance is generated by a rule-based system using established "
    "agronomic and plant pathology knowledge. It is NOT produced by a large "
    "language model. Always verify recommendations with a qualified agronomist "
    "or extension specialist before making significant management decisions."
)


@dataclass
class AiDoctorResponse:
    """Structured response returned by the AI Plant Doctor."""

    message: str
    """Primary guidance text."""

    suggestions: List[str]
    """Short, actionable bullet-point suggestions."""

    related_topics: List[str]
    """Topics the user can ask about next."""

    is_llm: bool = False
    """Always False – this service is rule-based, not LLM-backed."""

    disclaimer: str = _DISCLAIMER
    """Transparency note about the nature of this service."""


# ---------------------------------------------------------------------------
# Knowledge base
# Each entry: (compiled_pattern, response_builder_callable)
# The builder receives (message: str, scan_context: dict | None) -> Tuple[str, List[str], List[str]]
# Returns (message, suggestions, related_topics)
# ---------------------------------------------------------------------------

def _water_response(msg: str, ctx: Optional[Dict]) -> Tuple[str, List[str], List[str]]:
    return (
        (
            "Proper watering is one of the most important factors in plant health. "
            "Most crop plants prefer deep, infrequent watering that encourages "
            "roots to grow downward. Overwatering is a leading cause of root rot, "
            "fungal diseases, and nutrient leaching. Underwatering causes stress "
            "that makes plants susceptible to pests and diseases."
        ),
        [
            "Water at the base of the plant, not on the foliage.",
            "Check soil moisture by pressing a finger 2–3 cm into the soil before watering.",
            "Water in the morning so that any splashed foliage dries by midday.",
            "Use drip irrigation where possible to minimise foliar wetness.",
            "Tomatoes, peppers, and potatoes prefer consistently moist but never waterlogged soil.",
            "Fruit trees generally need deep watering every 7–14 days depending on rainfall.",
        ],
        ["sunlight", "soil health", "fertilizer", "disease prevention"],
    )


