def _blight_response(msg: str, ctx: Optional[Dict]) -> Tuple[str, List[str], List[str]]:
    # Enrich with scan context if available
    scan_info = ""
    if ctx:
        disease = ctx.get("disease_label", "")
        confidence = ctx.get("disease_confidence", 0)
        if disease and "blight" in disease.lower():
            scan_info = (
                f" Based on your recent scan ({disease}, confidence "
                f"{confidence:.0%}), prompt action is advised."
            )

    return (
        (
            "Blight is a broad term for diseases that cause rapid browning, "
            "wilting, and death of plant tissue. Early blight (Alternaria spp.) "
            "and late blight (Phytophthora spp.) are the most economically "
            "important blights of solanaceous crops (tomato, potato, pepper)."
            + scan_info
        ),
        [
            "Identify the specific blight type before choosing a fungicide (early vs late blight require different products).",
            "Early blight: look for brown lesions with concentric rings on lower leaves.",
            "Late blight: look for water-soaked, pale green lesions that darken rapidly.",
            "For early blight: apply chlorothalonil or mancozeb at 7–10 day intervals.",
            "For late blight: apply metalaxyl-M or cymoxanil immediately – this disease spreads extremely fast.",
            "Remove infected leaves carefully without shaking the plant, which spreads spores.",
            "Avoid overhead irrigation during periods of high disease pressure.",
        ],
        ["disease prevention", "watering", "tomato care", "potato care"],
    )


