    scan_info = ""
    if ctx:
        plant = ctx.get("plant_common_name", "")
        conf = ctx.get("plant_confidence", 0)
        if plant:
            scan_info = (
                f" Your recent scan of {plant} "
                f"(confidence {conf:.0%}) shows no signs of disease. "
            )

    return (
        (
            "A healthy plant is your best defence against diseases and pests. "
            "Maintaining optimal growing conditions – appropriate light, water, "
            "nutrition, and soil health – makes plants more resilient and better "
            "able to outgrow minor pest or disease pressure." + scan_info
        ),
        [
            "Continue current watering and fertilisation practices if the plant looks healthy.",
            "Scout weekly for early signs of pest activity or disease.",
            "Maintain crop rotation to prevent soilborne pathogen build-up.",
            "Apply preventive fungicide before forecast wet periods for susceptible crops.",
            "Record plant observations in a growing journal to track long-term health trends.",
        ],
        ["watering", "sunlight", "soil health", "disease prevention"],
    )


