def _general_response(msg: str, ctx: Optional[Dict]) -> Tuple[str, List[str], List[str]]:
    return (
        (
            "Welcome to PlantSathi AI Doctor! I can answer questions about plant "
            "care, watering, sunlight, soil health, fertilisation, pest management, "
            "disease prevention and treatment, and recovery from plant stress. "
            "Please provide more detail about your plant or situation so I can "
            "give you more targeted advice."
        ),
        [
            "Describe the symptoms you are observing (colour, texture, location on plant).",
            "Tell me which plant species or crop you are growing.",
            "Mention your growing environment (field, greenhouse, container).",
            "Ask about: watering, sunlight, soil, fertilizer, pests, disease, blight, mildew, rust.",
        ],
        ["watering", "sunlight", "soil health", "fertilizer", "disease prevention", "pests"],
    )


# ---------------------------------------------------------------------------
# Rule table: list of (regex_pattern, handler_function)
# ---------------------------------------------------------------------------
_RULES: List[Tuple[re.Pattern, Any]] = [
    (re.compile(r"\b(water|irrigat|drip|drought|dry|moisture|overwater|underwater)\b", re.I), _water_response),
    (re.compile(r"\b(sun|light|shade|uv|lux|photosynth|photosynthes)\b", re.I), _sunlight_response),
    (re.compile(r"\b(soil|ph|clay|sand|loam|drainage|compost|mulch|organic matter)\b", re.I), _soil_response),
    (re.compile(r"\b(fertiliz|fertilise|npk|nitrogen|phosphor|potassium|calcium|magnesium|nutrient|deficien)\b", re.I), _fertilizer_response),
    (re.compile(r"\b(pest|insect|aphid|whitefly|mite|caterpillar|thrip|bug|larv|worm)\b", re.I), _pest_response),
    (re.compile(r"\b(blight)\b", re.I), _blight_response),
    (re.compile(r"\b(rust)\b", re.I), _rust_response),
    (re.compile(r"\b(mildew|powdery)\b", re.I), _mildew_response),
    (re.compile(r"\b(disease|pathogen|fungus|fungal|bacteria|bacterial|virus|viral|infect|spot|rot|scab|canker)\b", re.I), _disease_prevention_response),
    (re.compile(r"\b(recover|treatment|treat|cure|heal|fix)\b", re.I), _recovery_response),
    (re.compile(r"\b(healthy|good|fine|ok|no disease|no problem|green|thriving)\b", re.I), _healthy_plant_response),
    (re.compile(r"\b(transplant|repot|pot|container|move|relocat)\b", re.I), _transplanting_response),
]


class AiDoctor:
    """
    Rule-based AI Plant Doctor.

    Matches user messages against a keyword rule table and returns
    structured, evidence-based plant care guidance.  When a scan context
    is provided (from a previous identification/diagnosis scan), responses
    are enriched with the actual prediction data.

    This service is entirely local and requires no API keys.
    """

    async def get_response(
        self,
        message: str,
        scan_context: Optional[Dict[str, Any]] = None,
    ) -> AiDoctorResponse:
        """
        Generate a rule-based response to a plant care question.

        Parameters
        ----------
        message:
            Natural-language query from the user.
        scan_context:
            Optional dict containing keys such as ``plant_common_name``,
            ``disease_label``, ``is_healthy``, ``plant_confidence``, and
            ``disease_confidence`` from a prior scan.

        Returns
        -------
        AiDoctorResponse
        """
        if not message or not message.strip():
            return AiDoctorResponse(
                message="Please ask a question about your plant and I will do my best to help.",
                suggestions=["Describe the symptoms you are seeing.", "Tell me which crop you are growing."],
                related_topics=["watering", "disease prevention", "pests"],
            )

        # Match against rule table (first matching rule wins)
        for pattern, handler in _RULES:
            if pattern.search(message):
                response_msg, suggestions, related_topics = handler(message, scan_context)
                logger.debug(
                    "AiDoctor matched pattern '%s' for message: %s",
                    pattern.pattern[:40],
                    message[:60],
                )
                return AiDoctorResponse(
                    message=response_msg,
                    suggestions=suggestions,
                    related_topics=related_topics,
                )

        # Context-aware fallback: use scan data if available
        if scan_context:
            ctx_msg, ctx_suggestions, ctx_topics = _recovery_response(message, scan_context)
            return AiDoctorResponse(
                message=(
                    "I couldn't identify a specific topic in your question, but based on "
                    "your recent scan here is some relevant guidance:\n\n" + ctx_msg
                ),
                suggestions=ctx_suggestions,
                related_topics=ctx_topics,
            )

        # Generic fallback
        general_msg, general_suggestions, general_topics = _general_response(message, scan_context)
        return AiDoctorResponse(
            message=general_msg,
            suggestions=general_suggestions,
            related_topics=general_topics,
        )


# Module-level singleton
ai_doctor = AiDoctor()
